import express from "express";
import cors from "cors";
import dotenv from "dotenv";

import authRoutes from "./routes/auth.js";
import menuRoutes from "./routes/menu.js";
import contentRoutes, { bannerRoutes, footerRoutes } from "./routes/content.js";
import categoriesRoutes from "./routes/categories.js";
import pagesRoutes from "./routes/pages.js";
import { robotsRouter, sitemapRouter } from "./routes/sitemap.js";
import userRoutes from "./routes/users.js";
import productRoutes from "./routes/products.js";
import productDetailsRoutes from "./routes/productDetails.js";
import productOptionValuesRoutes from "./routes/productOptionValues.js";
import settingsRoutes from "./routes/settings.js";
import wishlistRoutes from "./routes/wishlist.js";
import orderRoutes from "./routes/orders.js";
import uploadRoutes from "./routes/upload.js";
import adminAuditRoutes from "./routes/adminAudit.js";
import couponRoutes from "./routes/coupons.js";
import { assertJwtSecret } from "./middleware/auth.js";

dotenv.config();
assertJwtSecret();

// Warn once at startup when a deployed process has no origin allowlist: every
// browser call would be blocked with no hint as to why. Local development is
// expected to fall back to the localhost defaults, so it stays quiet there.
if (!(process.env.ALLOWED_ORIGINS || "").trim() && process.env.NODE_ENV === "production") {
  console.warn(
    "[cors] ALLOWED_ORIGINS is not set. Browser requests will be limited to the localhost defaults (http://localhost:5173, http://127.0.0.1:5173)."
  );
}

const app = express();

const DEFAULT_ALLOWED_ORIGINS = ["http://localhost:5173", "http://127.0.0.1:5173"];

function allowedOrigins() {
  const configured = (process.env.ALLOWED_ORIGINS || "")
    .split(",")
    .map((origin) => origin.trim())
    .filter(Boolean);

  return configured.length > 0 ? configured : DEFAULT_ALLOWED_ORIGINS;
}

// Middleware
app.use(
  cors({
    origin(origin, callback) {
      // Same-origin and non-browser callers send no Origin header.
      if (!origin || allowedOrigins().includes(origin)) {
        return callback(null, true);
      }
      return callback(null, false);
    },
  })
);
app.use(express.json());
app.use(express.urlencoded({ extended: false }));

// API Status Healthcheck
app.get("/api/health", (req, res) => {
  res.json({
    status: "online",
    service: "Marvel E-Commerce Express Backend API",
    architecture: "Frontend (React) -> Backend (Express REST API) -> Cloudinary / Supabase DB",
    roles_supported: ["user", "vendor", "admin", "super_admin"],
    cloudinary_active: Boolean(process.env.CLOUDINARY_CLOUD_NAME),
    timestamp: new Date().toISOString(),
  });
});

// API Routes
app.use("/api/auth", authRoutes);
app.use("/api/menu", menuRoutes);
app.use("/api/content", contentRoutes);
app.use("/api/content/banners", bannerRoutes);
app.use("/api/content/footer", footerRoutes);
app.use("/api/categories", categoriesRoutes);
app.use("/api/pages", pagesRoutes);
// The sitemap routers are mounted twice on purpose. `app.use` strips the
// mount path, so a router that serves "/" answers the request; `app.get`
// leaves the path alone, so a router that serves the full path answers it.
// Whichever shape the router uses, the file is served exactly once.
app.use("/api/sitemap.xml", sitemapRouter);
app.get("/api/sitemap.xml", sitemapRouter);
app.use("/api/robots.txt", robotsRouter);
app.get("/api/robots.txt", robotsRouter);
app.use("/api/users", userRoutes);
app.use("/api/settings", settingsRoutes);
// Mounted before productRoutes so `/:id/details` wins over the generic read.
app.use("/api/products", productDetailsRoutes);
app.use("/api/products", productRoutes);
app.use("/api/product-option-values", productOptionValuesRoutes);
app.use("/api/account/wishlist", wishlistRoutes);
app.use("/api/orders", orderRoutes);
app.use("/api/upload", uploadRoutes);
app.use("/api/admin/audit", adminAuditRoutes);
app.use("/api/coupons", couponRoutes);

// Fallback Route for unhandled /api requests
app.use("/api/*", (req, res) => {
  res.status(404).json({ error: `API route '${req.originalUrl}' not found.` });
});

// Terminal error handler: always answer with JSON, never Express's HTML page.
export function apiErrorHandler(err, req, res, next) {
  if (res.headersSent) return next(err);
  console.error("[api] unhandled error:", err);
  res.status(err.status || 500).json({ error: err.message || "Internal server error." });
}
app.use(apiErrorHandler);

export default app;

import app from "./app.js";
import dotenv from "dotenv";

dotenv.config();

const PORT = process.env.PORT || 5000;

const server = app.listen(PORT, () => {
  console.log(`=======================================================`);
  console.log(`🚀 Marvel Dedicated Backend API Server running on port ${PORT}`);
  console.log(`🔗 API Base URL: http://localhost:${PORT}/api`);
  console.log(`☁️ Cloudinary Upload Endpoint: http://localhost:${PORT}/api/upload`);
  console.log(`=======================================================`);
});

server.on("error", (err) => {
  if (err.code === "EADDRINUSE") {
    console.error(`\n⚠️  Port ${PORT} is already in use by another process.`);
    console.error(`   To free port ${PORT}, run: npx kill-port ${PORT} or fuser -k ${PORT}/tcp\n`);
  } else {
    console.error("Server startup error:", err);
  }
  process.exit(1);
});

